export const prayerTopics = [...new Set(prayers.map(p => p.topic))].sort();

export const prayerLifeStages = [...new Set(prayers.map(p => p.lifeStage))].sort();

export function getPrayerBySlug(slug: string): Prayer | undefined {
  return prayers.find(p => p.slug === slug);
}
